"""Teardown bookkeeping — pure, no Docker (T1.4).

A full `-m e2e` run once finished green while leaving a redis container, its network and both
volumes behind: every removal ran with `check=False` and nothing looked afterwards. The fix is
verification plus a session guard, and a guard that can never fire is worth nothing — so this
pins the two properties it stands on: `start()` registers, and `teardown()` deregisters *only*
when everything is really gone.

The order is pinned too: docker refuses to drop a network or a volume while a container still
holds it, so containers must be removed first.
"""

from __future__ import annotations

from typing import Any

import pytest
from harness import gramps_instance as gi


@pytest.fixture
def fake_docker(monkeypatch: pytest.MonkeyPatch) -> list[tuple[str, ...]]:
    """Record docker calls instead of making them, and never really sleep."""
    calls: list[tuple[str, ...]] = []

    def record(*args: str, **kwargs: Any) -> str:
        calls.append(args)
        return ""

    monkeypatch.setattr(gi, "docker", record)
    monkeypatch.setattr(gi.time, "sleep", lambda _seconds: None)
    monkeypatch.setattr(gi, "free_port", lambda: 54321)
    monkeypatch.setattr(gi.GrampsInstance, "_await_ready", lambda self: 1.0)
    monkeypatch.setattr(gi, "STARTED", [])
    return calls


def test_start_registers_the_instance(fake_docker: list[tuple[str, ...]]) -> None:
    instance = gi.GrampsInstance("deadbeef")
    instance.start()
    assert gi.STARTED == [instance], "the session guard can only see registered instances"


def test_teardown_deregisters_when_everything_is_gone(
    monkeypatch: pytest.MonkeyPatch, fake_docker: list[tuple[str, ...]]
) -> None:
    monkeypatch.setattr(gi, "resource_exists", lambda kind, name: False)
    instance = gi.GrampsInstance("deadbeef")
    instance.start()

    removed = instance.teardown()

    assert instance.leftovers == []
    assert gi.STARTED == []
    assert set(removed) == {
        instance.web,
        instance.redis,
        instance.network,
        instance.users_volume,
        instance.data_volume,
    }


def test_a_survivor_keeps_the_instance_registered(
    monkeypatch: pytest.MonkeyPatch, fake_docker: list[tuple[str, ...]]
) -> None:
    """The exact shape of the observed leak: the redis container refuses to go."""
    instance = gi.GrampsInstance("deadbeef")
    instance.start()
    monkeypatch.setattr(gi, "resource_exists", lambda kind, name: name == instance.redis)

    instance.teardown()

    assert instance.leftovers == [f"container:{instance.redis}"]
    assert gi.STARTED == [instance], "a leaked instance must stay visible to the session guard"


def test_teardown_retries_once_before_giving_up(
    monkeypatch: pytest.MonkeyPatch, fake_docker: list[tuple[str, ...]]
) -> None:
    """Removal is refused while a container is gone but not yet released — one retry covers it."""
    instance = gi.GrampsInstance("deadbeef")
    instance.start()
    seen: list[str] = []

    def exists_once(kind: str, name: str) -> bool:
        first_look = name not in seen
        seen.append(name)
        return first_look and name == instance.data_volume

    monkeypatch.setattr(gi, "resource_exists", exists_once)
    instance.teardown()

    assert instance.leftovers == []
    assert gi.STARTED == []


def test_containers_are_removed_before_network_and_volumes(
    monkeypatch: pytest.MonkeyPatch, fake_docker: list[tuple[str, ...]]
) -> None:
    monkeypatch.setattr(gi, "resource_exists", lambda kind, name: False)
    instance = gi.GrampsInstance("deadbeef")
    instance.start()
    fake_docker.clear()

    instance.teardown()

    kinds = [args[0] for args in fake_docker]
    assert kinds == ["rm", "rm", "network", "volume", "volume"]
